#!/usr/bin/env bash
# Created by Lokinya (lokinyauv-create). Generated by AI (Claude, Anthropic). Apache-2.0.
# Installs Tracker Calibration for the current user (no root):
#   the SteamVR driver, the app, a menu entry and autostart.
# Re-running it updates an existing install and keeps your calibration.
#   --no-restart   do not (re)start the app afterwards (used by the in-app updater)
set -euo pipefail
SRC="$(cd "$(dirname "$0")" && pwd)"
APP="$HOME/.local/share/fbt-calibrator"
DRV="$HOME/.local/share/SteamVR/drivers/fbtcal"
RESTART=1; [ "${1:-}" = "--no-restart" ] && RESTART=0

say() { echo "• $*"; }
command -v python3 >/dev/null || { echo "python3 is required / потрібен python3"; exit 1; }

say "Copying files / Копіюю файли → $APP"
mkdir -p "$APP"
rm -rf "$APP/app" "$APP/driver"
cp -r "$SRC/app" "$SRC/driver" "$APP/"
cp "$SRC/LICENSE" "$SRC/NOTICE" "$SRC/uninstall.sh" "$SRC/fbt-calibrator" "$APP/"
rm -rf "$APP/app/tests" "$APP/driver/build"
find "$APP" -name __pycache__ -prune -exec rm -rf {} +

if [ ! -f "$APP/driver/fbtcal/bin/linux64/driver_fbtcal.so" ]; then
  say "Building the SteamVR driver / Збираю драйвер"
  command -v cmake >/dev/null && command -v g++ >/dev/null || {
    echo "Need cmake and g++ (e.g. sudo dnf install cmake gcc-c++) / потрібні cmake і g++"; exit 1; }
  cmake -S "$APP/driver" -B "$APP/driver/build" -DCMAKE_BUILD_TYPE=Release >/dev/null
  cmake --build "$APP/driver/build" >/dev/null
fi

say "Python environment / Середовище Python"
[ -x "$APP/.venv/bin/python" ] || python3 -m venv --system-site-packages "$APP/.venv"
"$APP/.venv/bin/python" -m pip install -q --disable-pip-version-check openvr numpy
"$APP/.venv/bin/python" -c "import PySide6" 2>/dev/null || \
  "$APP/.venv/bin/python" -m pip install -q --disable-pip-version-check PySide6

say "Registering the driver with SteamVR / Реєструю драйвер у SteamVR"
VRPATHREG=""
for root in "$HOME/.local/share/Steam" "$HOME/.steam/steam" "$HOME/.var/app/com.valvesoftware.Steam/.local/share/Steam"; do
  for lib in "$root" $(grep -o '"path"[[:space:]]*"[^"]*"' "$root/steamapps/libraryfolders.vdf" 2>/dev/null | cut -d'"' -f4); do
    [ -x "$lib/steamapps/common/SteamVR/bin/vrpathreg.sh" ] && { VRPATHREG="$lib/steamapps/common/SteamVR/bin/vrpathreg.sh"; break 2; }
  done
done
[ -n "$VRPATHREG" ] || { echo "SteamVR not found — install SteamVR first / спершу встанови SteamVR"; exit 1; }
mkdir -p "$DRV"
cp -r "$APP/driver/fbtcal/." "$DRV/"
"$VRPATHREG" adddriver "$DRV" >/dev/null

say "Menu entry and autostart / Ярлик і автозапуск"
mkdir -p "$HOME/.local/bin" "$HOME/.local/share/applications"
ln -sf "$APP/fbt-calibrator" "$HOME/.local/bin/fbt-calibrator"
cat > "$HOME/.local/share/applications/fbt-calibrator.desktop" <<DESK
[Desktop Entry]
Type=Application
Name=Tracker Calibration
Name[uk]=Калібрування трекерів
Comment=T-pose calibration for SteamVR trackers; VRChat calibration from any pose
Comment[uk]=Т-поза → рівні трекери; калібрування VRChat у будь-якій позі
Exec=$HOME/.local/bin/fbt-calibrator --show
Icon=input-gaming
Categories=Game;Utility;
DESK

LAUNCHER_CFG="$HOME/.config/vr-autolauncher/config.json"
if [ -f "$LAUNCHER_CFG" ]; then
  # VR Auto Launcher starts it together with SteamVR.
  python3 - "$LAUNCHER_CFG" "$HOME/.local/bin/fbt-calibrator" <<'PY'
import json, sys
path, cmd = sys.argv[1:]
d = json.load(open(path))
old = next((a for a in d["apps"] if a["name"] in ("Калібрування трекерів", "Tracker Calibration")), None)
entry = {"name": "Калібрування трекерів", "enabled": True, "when": ["vrserver"], "trigger": "all",
         "delay": 3, "command": cmd, "running": ["fbt-calibrator"], "close_on_exit": True,
         "close_delay": 0, "keep_alive": True, "env": {}}
if old:
    old.update(command=cmd, running=["fbt-calibrator"])
else:
    d["apps"].append(entry)
json.dump(d, open(path, "w"), indent=1, ensure_ascii=False)
PY
  rm -f "$HOME/.config/autostart/fbt-calibrator.desktop"
else
  # No VR Auto Launcher: start at login; the app sleeps until SteamVR runs.
  mkdir -p "$HOME/.config/autostart"
  sed 's/ --show$//' "$HOME/.local/share/applications/fbt-calibrator.desktop" > "$HOME/.config/autostart/fbt-calibrator.desktop"
fi

if [ "$RESTART" = 1 ]; then
  pkill -x fbt-calibrator 2>/dev/null || true
  for _ in $(seq 20); do pgrep -x fbt-calibrator >/dev/null || break; sleep 0.25; done
  setsid -f "$HOME/.local/bin/fbt-calibrator" >/dev/null 2>&1
fi
echo "Done / Готово. Restart SteamVR once so the driver loads / Перезапусти SteamVR один раз."
